"""`.Manual eye sliders`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.Manual eye sliders'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Result', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
    t.socket('INPUT', 'Eye premade', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
    t.socket('INPUT', 'B', 'NodeSocketColor', default_value=(1.0, 1.0, 1.0, 1.0))
    t.socket('INPUT', 'Fac', 'NodeSocketFloat', subtype='FACTOR', default_value=0.5, min_value=0.0, max_value=1.0)

    t.node('NodeFrame', 'Frame.001', props={
        'location': (-699.15796, 227.78947),
        'width': 1541.1578,
        'height': 716.6316,
        'label': 'Setup Eye color here',
        'color': (0.9687825, 0.7442364, 1.0),
    })
    t.node('NodeFrame', 'Frame.004', parent='Frame.001', props={
        'location': (729.78955, -63.052628),
        'width': 577.8947,
        'height': 272.42105,
        'label': 'Change the pupil color',
        'color': (0.968782, 0.744236, 1.0),
    })
    t.node('NodeFrame', 'Frame.008', parent='Frame.001', props={
        'location': (71.052734, -399.0526),
        'width': 536.4829,
        'height': 288.2105,
        'label': 'Level the pupil texture',
        'color': (0.968782, 0.744236, 1.0),
    })
    t.node('NodeFrame', 'Frame.007', parent='Frame.001', props={
        'location': (29.36853, -39.684204),
        'width': 298.73682,
        'height': 272.42108,
        'label': 'Gradient sharpness',
        'color': (0.968782, 0.744236, 1.0),
    })
    t.node('NodeGroupInput', 'Group Input', props={
        'location': (-898.9877, 0.0),
    })
    t.node('ShaderNodeMix', 'Mix.005', parent='Frame.001', inputs={'B_Color': (1.0, 1.0, 1.0, 1.0)}, outputs={'Result_Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (404.11282, -107.20921),
        'width': 183.43027,
        'data_type': 'RGBA',
        'blend_type': 'MULTIPLY',
    })
    t.node('ShaderNodeValToRGB', 'ColorRamp.003', parent='Frame.004', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, color_ramp={'color_mode': 'RGB', 'interpolation': 'B_SPLINE', 'hue_interpolation': 'NEAR', 'elements': [{'position': 0.0, 'color': (0.07670228, 0.1181008, 0.66772777, 1.0)}, {'position': 0.7101447, 'color': (0.5507908, 0.98554486, 0.92534196, 1.0)}, {'position': 1.0, 'color': (0.82770437, 1.0, 0.9793871, 1.0)}]}, props={
        'location': (308.21912, -39.831024),
    })
    t.node('ShaderNodeHueSaturation', 'Hue Saturation Value.001', parent='Frame.004', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (29.138062, -75.85861),
        'width': 150.0,
    })
    t.node('ShaderNodeMix', 'Mix.004', parent='Frame.008', inputs={'B_Color': (1.0, 1.0, 1.0, 1.0)}, outputs={'Result_Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (323.41238, -39.405487),
        'width': 183.43027,
        'data_type': 'RGBA',
        'blend_type': 'MULTIPLY',
    })
    t.node('ShaderNodeValToRGB', 'ColorRamp.004', parent='Frame.008', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, color_ramp={'color_mode': 'RGB', 'interpolation': 'LINEAR', 'hue_interpolation': 'NEAR', 'elements': [{'position': 0.04710145, 'color': (0.0, 0.0, 0.0, 1.0)}, {'position': 1.0, 'color': (1.0, 1.0, 1.0, 1.0)}]}, props={
        'location': (29.520996, -56.29373),
    })
    t.node('ShaderNodeValToRGB', 'ColorRamp.001', parent='Frame.007', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, color_ramp={'color_mode': 'RGB', 'interpolation': 'LINEAR', 'hue_interpolation': 'NEAR', 'elements': [{'position': 0.0, 'color': (0.0, 0.0, 0.0, 1.0)}, {'position': 0.8659422, 'color': (1.0, 1.0, 1.0, 1.0)}]}, props={
        'location': (29.489746, -39.78929),
    })
    t.node('NodeGroupOutput', 'Group Output', parent='Frame.001', props={
        'location': (1371.8997, -206.2401),
    })

    t.link('ColorRamp.004', 'Color', 'Mix.004', 'A_Color')
    t.link('Mix.005', 'Result_Color', 'Hue Saturation Value.001', 'Color')
    t.link('ColorRamp.001', 'Color', 'Mix.005', 'A_Color')
    t.link('Hue Saturation Value.001', 'Color', 'ColorRamp.003', 'Fac')
    t.link('Group Input', 'B', 'Mix.005', 'B_Color')
    t.link('Group Input', 'B', 'Mix.004', 'B_Color')
    t.link('Group Input', 'B', 'ColorRamp.004', 'Fac')
    t.link('Group Input', 'Fac', 'ColorRamp.001', 'Fac')
    t.link('ColorRamp.003', 'Color', 'Group Output', 'Result')
    return t
